+    /* 角度变了 ⇒ R 的整幅内容作废，交给 vmap_rot_track 重烘（见它的条件）。 */
+    view->last_pan_px = INT32_MIN;
+    view->last_pan_py = INT32_MIN;
+    vmap_view_apply_canvas_pos(view, view->pan_dx, view->pan_dy);
