   320	static void vmap_perf_frame_end(uint32_t zoom, uint32_t dirty)
   321	{
   322	    uint32_t total;
   323	    uint32_t now;
   324	    uint32_t tickd;
   325	    uint32_t iacc;
   326	    uint32_t imiss;
   327	    uint32_t dacc;
   328	    uint32_t dmiss;
   329	    uint32_t cps;
   330	
   331	    if (!s_pf_usable || !s_pf_in_frame) {
   332	        return;
   333	    }
   334	    s_pf_in_frame = false;
   335	
   336	    total = vmap_perf_cyc() - s_pf_t0;
   337	    tickd = (uint32_t)(clock_systime_ticks() - s_pf_tick0);
   338	    iacc = VMAP_PERF_CACHE_IACR - s_pf_iacc0;
   339	    imiss = VMAP_PERF_CACHE_IMCR - s_pf_imiss0;
   340	    dacc = VMAP_PERF_CACHE_DACR - s_pf_dacc0;
   341	    dmiss = VMAP_PERF_CACHE_DMCR - s_pf_dmiss0;
   342	    cps = (s_pf_stores != 0u) ? (s_pf_tile / s_pf_stores) : 0u;
   343	    {
   344	        uint32_t h1 = 0u;
   345	        uint32_t h2 = 0u;
   346	        uint32_t hc = 0u;
   347	
   348	        vmap_blit_stats(vmap_blit_get(), &h1, &h2, &hc);
   349	        s_pf_hop1 = h1 - s_pf_hop0[0];
   350	        s_pf_hop2 = h2 - s_pf_hop0[1];
   351	        s_pf_cpuc = hc - s_pf_hop0[2];
   352	    }
   353	    now = lv_tick_get();
   354	    if (s_pf_last_log != 0u && lv_tick_elaps(s_pf_last_log) < VMAP_PERF_LOG_GAP_MS) {
   355	        return;
   356	    }
   357	    s_pf_last_log = now;
   358	
   359	    /* 全部是原始周期数，单位只在主机侧按 cyc_tot/(tickd*10ms) 反解。
   360	     * dirty 是这一帧的脏区条数：0 = 全量重画，>0 = scroll 补边。
   361	     * st/by = 瓦片光栅化发出的 store 次数与字节数；cps = cyc_tile/st —— 判成本模型：
   362	     *   cps ≈ 88  ⇒ 每次 store 一次总线事务（成本 ∝ store 次数）
   363	     *   cyc_tile/(by/4) ≈ 88 而 cps 不成 ... 见 docs/map/perf/MEASUREMENTS.md
   364	     * i/d = SoC 缓存的 access/miss 增量（判取指命中率）。 */
   365	    /* 超长帧无条件 WARNING；正常帧留 INFO（用户 2026-09-26）。 */
   366	    syslog((total > (VMAP_PERF_SLOW_FRAME_MS * 240u * 1000u)) ? LOG_WARNING : LOG_INFO,
   367	        "[vperf] frame z=%u dirty=%u tickd=%u cyc_begin=%u cyc_warm=%u cyc_tile=%u cyc_nav=%u cyc_label=%u cyc_track=%u cyc_tot=%u tiles=%u warms=%u labels=%u st=%u by=%u cps=%u i=%u/%u d=%u/%u scr=%u lscr=%u inv=%u meta=%u hop1=%u hop2=%u cpuc=%u hz=%u",
   368	        (unsigned)zoom, (unsigned)dirty, (unsigned)tickd,
   369	        (unsigned)s_pf_begin, (unsigned)s_pf_warm,
   370	        (unsigned)s_pf_tile, (unsigned)s_pf_nav,
   371	        (unsigned)s_pf_label, (unsigned)s_pf_track,
   372	        (unsigned)total,
   373	        (unsigned)s_pf_n_tiles, (unsigned)s_pf_n_warms,
   374	        (unsigned)s_pf_n_labels,
   375	        (unsigned)s_pf_stores, (unsigned)s_pf_bytes, (unsigned)cps,
   376	        (unsigned)iacc, (unsigned)imiss, (unsigned)dacc, (unsigned)dmiss,
   377	        (unsigned)s_pf_scroll, (unsigned)s_pf_lscroll,
   378	        (unsigned)s_pf_inval, (unsigned)s_pf_meta,
   379	        (unsigned)s_pf_hop1, (unsigned)s_pf_hop2, (unsigned)s_pf_cpuc,
   380	        (unsigned)SystemCoreClock);
   381	
   382	    /* 【临时取证】cyc_tile 按图元拆开：多边形 / 面填充 / 圆盘，外加两个工作量
   383	     * 计数（cross = 逐行软除次数，scan = 行×边 扫描次数）。测完即撤。 */
   384	    vmap_render_prim_get(&s_prim);
   385	    syslog(LOG_DEBUG,
   386	        "[vperf] prim polyfp=%u npfp=%u poly=%u np=%u disc=%u nd=%u cross=%u scan=%u h=%u,%u,%u,%u,%u,%u cn=%u,%u,%u,%u,%u,%u",
   387	        (unsigned)(s_prim.poly_fp - s_prim0.poly_fp),
   388	        (unsigned)(s_prim.n_poly_fp - s_prim0.n_poly_fp),
   389	        (unsigned)(s_prim.poly - s_prim0.poly),
   390	        (unsigned)(s_prim.n_poly - s_prim0.n_poly),
   391	        (unsigned)(s_prim.disc - s_prim0.disc),
   392	        (unsigned)(s_prim.n_disc - s_prim0.n_disc),
   393	        (unsigned)(s_prim.cross - s_prim0.cross),
   394	        (unsigned)(s_prim.scan - s_prim0.scan),
   395	        (unsigned)s_prim.hist[0], (unsigned)s_prim.hist[1],
   396	        (unsigned)s_prim.hist[2], (unsigned)s_prim.hist[3],
   397	        (unsigned)s_prim.hist[4], (unsigned)s_prim.hist[5],
   398	        (unsigned)s_prim.cyc_n[0], (unsigned)s_prim.cyc_n[1],
   399	        (unsigned)s_prim.cyc_n[2], (unsigned)s_prim.cyc_n[3],
   400	        (unsigned)s_prim.cyc_n[4], (unsigned)s_prim.cyc_n[5]);
   401	}
