   428	/*
   429	 * PSRAM 通路自检（开机一次，打一行）。
   430	 *
   431	 * 目的：把"渲染为什么慢"拆成**每次访问的固定开销**与**字节速率**两件事。
   432	 * 手法：同样大小，分别用 4 字节逐字写、32 字节块写（stmia）、4 字节逐字读各跑
   433	 * 一遍，比周期数。判据（blk_w / word_w 的百分比）：
   434	 *
   435	 *   ≈ 12%  ⇒ 写通路会把块写合并成突发：`vmap_render.c` 的 32 字节块写
   436	 *            （fill_run_u16 / vmap_render_clear）已经赚到；
   437	 *   ≈ 100% ⇒ 写通路不合并、时间花在**字节**上：块写白做（该回滚），真正的
   438	 *            杠杆是减少要写的字节数，而不是换存储方式。
   439	 *
   440	 * 读一遍只作参照；注意它可能部分命中 D-cache，所以读数字是下界。
   441	 */
   442	#define VMAP_PERF_PSRAM_BYTES (128 * 1024)
   443	
   444	typedef struct {
   445	    uint32_t w[8];
   446	} vmap_perf_blk32_t;
   447	
   448	static void vmap_perf_psram_probe(void)
   449	{
   450	    uint8_t * buf = (uint8_t *)vmap_malloc(VMAP_PERF_PSRAM_BYTES);
   451	    vmap_perf_blk32_t blk;
   452	    uint32_t c0;
   453	    uint32_t c_word;
   454	    uint32_t c_blk;
   455	    uint32_t c_read;
   456	    uint32_t sum = 0;
   457	    int i;
   458	
   459	    if (buf == NULL) {
   460	        syslog(LOG_WARNING, "[vperf] psram probe: 分配失败，跳过\n");
   461	        return;
   462	    }
   463	    for (i = 0; i < 8; i++) {
   464	        blk.w[i] = 0xa5a5a5a5u;
   465	    }
   466	
   467	    memset(buf, 0, VMAP_PERF_PSRAM_BYTES);   /* 先热一遍，别把首次触碰算进去 */
   468	
   469	    c0 = vmap_perf_cyc();
   470	    for (i = 0; i < VMAP_PERF_PSRAM_BYTES; i += 4) {
   471	        *(uint32_t *)(void *)(buf + i) = 0xa5a5a5a5u;
   472	    }
   473	    __asm__ volatile("" ::: "memory");
   474	    c_word = vmap_perf_cyc() - c0;
   475	
   476	    c0 = vmap_perf_cyc();
   477	    for (i = 0; i < VMAP_PERF_PSRAM_BYTES; i += (int)sizeof(blk)) {
   478	        *(vmap_perf_blk32_t *)(void *)(buf + i) = blk;
   479	    }
   480	    __asm__ volatile("" ::: "memory");
   481	    c_blk = vmap_perf_cyc() - c0;
   482	
   483	    c0 = vmap_perf_cyc();
   484	    for (i = 0; i < VMAP_PERF_PSRAM_BYTES; i += 4) {
   485	        sum += *(const uint32_t *)(const void *)(buf + i);
   650	    double lon;
   651	    double lat;
   652	    double render_lon;
   653	    double render_lat;
   654	    double pan_dx;
   655	    double pan_dy;
   656	    int zoom;
   657	    double scale;
   658	    bool follow_mode;
   659	    int32_t last_arrow_angle10;
   660	    /** @brief 箭头当前**显示**角度（0.1°，补间中间值可能未归一化）；INT32_MIN=未初始化。 */
   661	    int32_t disp_arrow_angle10;
   662	    /** @brief 显示偏置（y）：只影响画布与箭头的屏幕位置，不进跟车/rebase 数学。 */
   663	    int32_t y_bias;
   664	    int32_t last_pan_px;
   665	    int32_t last_pan_py;
   666	    /** @brief 航向朝上：画布按航向旋转显示（画布本身仍正北向上）。 */
   667	    bool heading_up;
   668	    /** @brief 航向是否已初始化（首个有效 course 之前不做低通）。 */
   669	    bool heading_valid;
   670	    /** @brief 低通后的航向（度，正北 0，顺时针）。 */
   671	    double heading_deg;
   672	    /** @brief 已下发给画布的旋转角（0.1°，顺时针，0..3599）。 */
   673	    int32_t rot10;
   674	    /** @brief 上一次整幅重烘的时刻（用于重烘限频）。 */
   675	    uint32_t last_bake_ms;
   676	    /** @brief 航向朝上时也烘路名（A/B 用；默认关，文字会转成斜字）。 */
   677	    bool rot_labels;
   678	    /** @brief 航向朝上时的正立路名对象（不烘进画布）；位置见 rlx/rly（bake 时算）。 */
   679	    lv_obj_t * rot_label[VMAP_ROT_LABEL_MAX];
   680	    int32_t rlx[VMAP_ROT_LABEL_MAX];
   681	    int32_t rly[VMAP_ROT_LABEL_MAX];
   682	    uint8_t rot_label_n;
   683	    /* ===== 航向朝上：屏幕对齐的旋转缓冲 R =====
   684	     *
   685	     * 画布 C 仍是**正北向上**的渲染目标；R 是"按 rot10 转好、屏幕对齐"的视图，
   686	     * 由 EPIC 旋转烘焙（`myvendor_epic_rotate`）。跟车时只移动 R 的对象（便宜），
   687	     * 不用每次平移都重转整幅 —— 这是 2026-10-27 那轮 3 fps 的根因。
   688	     */
   689	    uint16_t * rbuf;
   690	    lv_obj_t * rcanvas;
   691	    int32_t rw;
   692	    int32_t rh;
   693	    uint32_t rstride;
   694	    int32_t r_margin;
   695	    /** @brief R 烘焙时的跟车 pan（与 r_rot10 一起定义"R 里的内容是哪一帧"）。 */
   696	    double r_pan_x;
   697	    double r_pan_y;
   698	    /** @brief R 烘焙时的旋转角。 */
   699	    int32_t r_rot10;
   700	    vmap_tile_cache_t * cache;
   701	    vmap_point_t * scratch;
   702	    /** @brief 道路要素索引缓冲（每张瓦片一次扫描用；创建时分配，全局绑定）。 */
   703	    vmap_road_ref_t * road_refs;
   704	    vmap_label_cand_t * labels;
   705	    vmap_label_retained_t * label_retained;
   706	    vmap_label_collector_t label_col;
   707	    const lv_font_t * font;
   708	    uint32_t map_rev;
   709	    uint32_t render_rev;
   710	    int32_t pump_tx;
   711	    int32_t pump_ty;
   712	    int32_t pump_tx_min;
   713	    int32_t pump_ty_min;
   714	    int32_t pump_tx_max;
   715	    int32_t pump_ty_max;
   716	    int pump_cx;
   717	    int pump_cy;
   718	    uint8_t pump_phase;
   719	    uint8_t restamp_pending;
   720	    uint8_t pump_need_region;
   721	    uint8_t pump_dirty_n;
   722	    int paint_zoom;
   723	    double paint_scale;
   724	    int32_t pump_dirty_x1[VMAP_RENDER_DIRTY_MAX];
   725	    int32_t pump_dirty_y1[VMAP_RENDER_DIRTY_MAX];
   726	    int32_t pump_dirty_x2[VMAP_RENDER_DIRTY_MAX];
   727	    int32_t pump_dirty_y2[VMAP_RENDER_DIRTY_MAX];
   728	    struct vmap_track * track;
   729	#if VMAP_ROUTE_ENABLE
   730	    struct vmap_route * route;
   731	#endif
   732	};
