   749	/**
   750	 * @brief 把箭头角度从当前显示值补间到目标角（0.1°）。
   751	 * @param view       视图。
   752	 * @param angle10    目标角，0..3599。
   753	 * @param allow_anim false 时立即到位（首帧 / 隐藏后重新出现 / 正好掉头）。
   754	 */
   755	static void vmap_arrow_apply(vmap_view_t * view, int32_t angle10, bool allow_anim)
   756	{
   757	    int32_t cur;
   758	    int32_t delta;
   759	    lv_anim_t a;
   760	
   761	    if (view == NULL || view->arrow == NULL) {
   762	        return;
   763	    }
   764	
   765	    cur = view->disp_arrow_angle10;
   766	    if (cur == INT32_MIN || !allow_anim) {
   767	        lv_anim_delete(view, vmap_arrow_angle_exec);
   768	        view->disp_arrow_angle10 = angle10;
   769	        lv_img_set_angle(view->arrow, angle10);
   770	        return;
   771	    }
   772	
   773	    /* 最短弧：结果 -1800..1799（同模空间，cur 未归一化也成立）。 */
   774	    delta = ((angle10 - cur + 3600 + 1800) % 3600) - 1800;
   775	    if (abs(delta) < 30 || abs(delta) >= 1800) {
   776	        lv_anim_delete(view, vmap_arrow_angle_exec);
   777	        view->disp_arrow_angle10 = angle10;
   778	        lv_img_set_angle(view->arrow, angle10);
   779	        return;
   780	    }
   781	
   782	    lv_anim_delete(view, vmap_arrow_angle_exec);
   783	    lv_anim_init(&a);
   784	    lv_anim_set_var(&a, view);
   785	    lv_anim_set_values(&a, cur, cur + delta);
   786	    lv_anim_set_duration(&a, 180);
   787	    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
   788	    lv_anim_set_exec_cb(&a, vmap_arrow_angle_exec);
   789	    lv_anim_start(&a);
   790	}
