   792	static void tile_range(int32_t center_x, int32_t center_y, int32_t canvas_w,
   793	    int32_t canvas_h, double scale, int32_t ring,
   794	    int32_t * tx_min, int32_t * ty_min, int32_t * tx_max, int32_t * ty_max)
   795	{
   796	    const int32_t tile_size = 256;
   797	    double half_w = (canvas_w / 2.0) / scale;
   798	    double half_h = (canvas_h / 2.0) / scale;
   799	    double pad = (double)ring * tile_size;
   800	    double left = (double)center_x - half_w - pad;
   801	    double top = (double)center_y - half_h - pad;
   802	    double right = (double)center_x + half_w + pad;
   803	    double bottom = (double)center_y + half_h + pad;
   804	
   805	    *tx_min = (int32_t)(left / tile_size) - (left < 0 ? 1 : 0);
   806	    *ty_min = (int32_t)(top / tile_size) - (top < 0 ? 1 : 0);
   807	    *tx_max = (int32_t)(right / tile_size);
   808	    *ty_max = (int32_t)(bottom / tile_size);
   809	}
