   818	    if (view == NULL || view->rcanvas == NULL) {
   819	        return;
   820	    }
   821	
   822	    lv_obj_set_pos(view->rcanvas,
   823	        (lv_coord_t)(-view->r_margin + sx),
   824	        (lv_coord_t)(-view->r_margin + sy + view->y_bias));
   825	
   826	    /* 正立路名跟着 R 一起平移（基准位置是上一次 bake 时算的屏幕坐标）。
   827	     * y_bias 统一在这里加，这样导航横幅出现/消失时它们和画布一起挪。 */
   828	    for (i = 0; i < (int32_t)view->rot_label_n; i++) {
   829	        lv_obj_set_pos(view->rot_label[i], (lv_coord_t)(view->rlx[i] + sx),
   830	            (lv_coord_t)(view->rly[i] + sy + view->y_bias));
   831	    }
   832	}
