   851	/**
   852	 * @brief 把本帧收集到的路名按"旋转后的屏幕位置"摆成正立文本对象。
   853	 * @details 文本不烘进画布（否则会跟着地图转成斜字）；位置 = R 中心 +
   854	 *          R(θ)·(画布点 - 骑手点)，再换算到 map_area 坐标。同名只留一条。
   855	 */
   856	static void vmap_rot_labels_update(vmap_view_t * view, int32_t pivot_x,
   857	    int32_t pivot_y)
   858	{
   859	    const double th = (double)view->rot10 * 0.1 * M_PI / 180.0;
   860	    const double c = cos(th);
   861	    const double s = sin(th);
   862	    const char * taken[VMAP_ROT_LABEL_MAX];
   863	    int32_t i;
   864	    int32_t n = 0;
   865	
   866	    if (!view->rot_labels || view->font == NULL || view->label_col.count <= 0) {
   867	        for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
   868	            lv_obj_add_flag(view->rot_label[i], LV_OBJ_FLAG_HIDDEN);
   869	        }
   870	        view->rot_label_n = 0;
   871	        return;
   872	    }
   873	
   874	    for (i = 0; i < view->label_col.count && n < VMAP_ROT_LABEL_MAX; i++) {
   875	        const vmap_label_cand_t * it = &view->label_col.items[i];
   876	        const double dx = (double)it->x - (double)pivot_x;
   877	        const double dy = (double)it->y - (double)pivot_y;
   878	        const int32_t rx = (int32_t)lround((double)view->rw / 2.0
   879	            + (c * dx - s * dy));
   880	        const int32_t ry = (int32_t)lround((double)view->rh / 2.0
   881	            + (s * dx + c * dy));
