  1589	        return NULL;
  1590	    }
  1591	
  1592	    memset(view->cbuf, 0, (size_t)view->stride * (size_t)view->h);
  1593	
  1594	    /*
  1595	     * 搬运后端自检（一次性，`[vblit]` 行）：拿真机画布几何测"同一块缓冲内
  1596	     * 源/目的矩形重叠"的搬运能不能交给 EPIC。放在这里是因为画布尺寸刚定下、
  1597	     * 还没有任何一帧在跑，而且自检缓冲用完立即释放。详见 vmap_blit.h。
  1598	     */
  1599	    vmap_blit_probe(view->w, view->h);
  1600	
  1601	    view->scratch = (vmap_point_t *)vmap_malloc(sizeof(vmap_point_t) * VMAP_SCRATCH_CAP);
  1602	
  1603	    /* 航向朝上用的屏幕对齐旋转缓冲 R（视口 + 四周余量）。分配不到就退回
  1604	     * "LVGL 直接旋转画布"的老路径（慢但能用）。 */
  1605	    view->r_margin = VMAP_ROT_MARGIN;
  1606	    view->rw = view_w + 2 * view->r_margin;
  1607	    view->rh = view_h + 2 * view->r_margin;
  1608	    view->rstride = lv_draw_buf_width_to_stride(view->rw, LV_COLOR_FORMAT_RGB565);
  1609	    view->rbuf = (uint16_t *)vmap_malloc((size_t)view->rstride * (size_t)view->rh);
  1610	    if (view->rbuf != NULL) {
  1611	        memset(view->rbuf, 0, (size_t)view->rstride * (size_t)view->rh);
  1612	    }
  1613	    /* 道路索引：只分配一次；失败只是回退逐 class 扫描，不影响可用性。 */
  1614	    view->road_refs = (vmap_road_ref_t *)vmap_malloc(
  1615	        sizeof(vmap_road_ref_t) * VMAP_ROAD_INDEX_CAP);
  1616	    view->labels = (vmap_label_cand_t *)vmap_malloc(sizeof(vmap_label_cand_t) * VMAP_LABEL_CAP);
  1617	    view->label_retained = (vmap_label_retained_t *)vmap_malloc(
  1618	        sizeof(vmap_label_retained_t) * VMAP_LABEL_RETAIN_CAP);
  1619	    view->cache = vmap_tile_cache_create();
  1620	    if (!view->scratch || !view->labels || !view->label_retained || !view->cache) {
  1621	        vmap_view_destroy(view);
  1622	        return NULL;
  1623	    }
  1624	
  1625	    if (view->road_refs) {
  1626	        vmap_render_bind_road_index(view->road_refs, VMAP_ROAD_INDEX_CAP);
  1627	    } else {
  1628	        syslog(LOG_WARNING,
  1629	            "[vmap] road index unavailable (%d), fallback to per-class scan",
  1630	            VMAP_ROAD_INDEX_CAP);
  1631	        vmap_render_bind_road_index(NULL, 0);
  1632	    }
  1633	
  1634	    vmap_label_collector_init(&view->label_col, view->labels, VMAP_LABEL_CAP,
  1635	        view->label_retained, VMAP_LABEL_RETAIN_CAP,
  1636	        view->w, view->h, view->view_w, view->view_h, view->margin);
  1637	
  1638	    view->canvas = lv_canvas_create(parent);
  1639	    lv_canvas_set_buffer(view->canvas, view->cbuf, view->w, view->h,
  1640	        LV_COLOR_FORMAT_RGB565);
  1641	    lv_obj_remove_style_all(view->canvas);
  1642	    lv_obj_set_size(view->canvas, view->w, view->h);
  1643	    lv_obj_set_pos(view->canvas, -margin, -margin);
  1644	    /* 首帧 render_finish 前不要把 PSRAM 噪声送到 LCD。 */
  1645	    lv_obj_add_flag(view->canvas, LV_OBJ_FLAG_HIDDEN);
  1646	
  1647	    /* 屏幕对齐的旋转缓冲对象（航向朝上时才显示）。 */
  1648	    if (view->rbuf != NULL) {
  1649	        view->rcanvas = lv_canvas_create(parent);
  1650	        lv_canvas_set_buffer(view->rcanvas, view->rbuf, view->rw, view->rh,
  1651	            LV_COLOR_FORMAT_RGB565);
  1652	        lv_obj_remove_style_all(view->rcanvas);
  1653	        lv_obj_set_size(view->rcanvas, view->rw, view->rh);
  1654	        vmap_rot_place(view, 0, 0);
  1655	        lv_obj_add_flag(view->rcanvas, LV_OBJ_FLAG_HIDDEN);
  1656	    } else {
  1657	        syslog(LOG_WARNING,
  1658	            "[vmap] rotated buffer unavailable (%dx%d) → heading-up disabled",
  1659	            (int)view->rw, (int)view->rh);
  1660	    }
  1661	
  1662	    /* 航向朝上时的正立路名：独立文本对象（不烘进画布，否则会转成斜字）。 */
  1663	    {
  1664	        int32_t i;
  1665	
  1666	        view->rot_labels = true;
  1667	        for (i = 0; i < VMAP_ROT_LABEL_MAX; i++) {
  1668	            lv_obj_t * l = lv_label_create(parent);
  1669	
  1670	            lv_obj_remove_style_all(l);
  1671	            lv_obj_remove_flag(l, LV_OBJ_FLAG_CLICKABLE);
  1672	            lv_obj_remove_flag(l, LV_OBJ_FLAG_SCROLLABLE);
  1673	            if (view->font != NULL) {
  1674	                lv_obj_set_style_text_font(l, view->font, 0);
  1675	            }
  1676	            lv_obj_add_flag(l, LV_OBJ_FLAG_HIDDEN);
  1677	            view->rot_label[i] = l;
  1678	        }
  1679	        view->rot_label_n = 0;
  1680	    }
  1681	
  1682	    /* 帧率探针：挂在显示对象上，只挂一次（见 vmap_fps_probe_cb 的说明）。 */
  1683	    if (!s_fps_hooked) {
  1684	        lv_display_t * disp = lv_obj_get_display(view->canvas);
  1685	
  1686	        if (disp != NULL) {
  1687	            lv_display_add_event_cb(disp, vmap_fps_probe_cb, LV_EVENT_ALL, NULL);
  1688	            s_fps_hooked = true;
  1689	        }
  1690	    }
  1691	
  1692	    vmap_view_set_tile_dir(view, VMAP_TILE_DIR);
  1693	    return view;
  1694	}
