  1696	/**
  1697	 * @brief 销毁视图：释放画布与瓦片缓存。
  1698	 */
  1699	void vmap_view_destroy(vmap_view_t * view)
  1700	{
  1701	    if (!view) {
  1702	        return;
  1703	    }
  1704	
  1705	    /* 动画回调以 view 为 var，必须先停，避免 view 释放后回调访问野指针。 */
  1706	    lv_anim_delete(view, vmap_arrow_angle_exec);
  1707	
  1708	    view->track = NULL;
  1709	
  1710	    if (view->canvas) {
  1711	        lv_obj_delete(view->canvas);
  1712	        view->canvas = NULL;
  1713	    }
  1714	    if (view->arrow) {
  1715	        lv_obj_delete(view->arrow);
  1716	    }
  1717	    if (view->rcanvas) {
  1718	        lv_obj_delete(view->rcanvas);
  1719	        view->rcanvas = NULL;
  1720	    }
  1721	    if (view->rbuf) {
  1722	        vmap_free(view->rbuf);
  1723	        view->rbuf = NULL;
  1724	    }
  1725	    if (view->cbuf && !view->cbuf_arena) {
  1726	        vmap_free(view->cbuf);
  1727	    }
  1728	    if (view->scratch) {
  1729	        vmap_free(view->scratch);
  1730	    }
  1731	    if (view->labels) {
  1732	        vmap_free(view->labels);
  1733	    }
  1734	    if (view->label_retained) {
  1735	        vmap_free(view->label_retained);
  1736	    }
  1737	    /* 先解绑再释放：渲染路径不能拿着即将释放的索引。只解自己的绑定——换主题
  1738	     * 重建 shell 时可能"先建新视图再毁旧视图"，无条件解绑会把新视图的索引也
  1739	     * 摘掉，之后静默退回逐 class 扫描（只是慢，不报错）。 */
  1740	    if (vmap_render_road_index() == view->road_refs) {
  1741	        vmap_render_bind_road_index(NULL, 0);
  1742	    }
  1743	    if (view->road_refs) {
  1744	        vmap_free(view->road_refs);
  1745	        view->road_refs = NULL;
  1746	    }
  1747	    vmap_tile_cache_destroy(view->cache);
  1748	    free(view);
  1749	}
