  1894	static void vmap_follow_log(const vmap_view_t * view, double lon, double lat)
  1895	{
  1896	    static uint32_t s_last;
  1897	
  1898	    if (!view) {
  1899	        return;
  1900	    }
  1901	    if (s_last != 0u && lv_tick_elaps(s_last) < 2000u) {
  1902	        return;
  1903	    }
  1904	    s_last = lv_tick_get();
  1905	    /* 几何诊断（用户 2026-09-25 报"导航中箭头不居中"）：把视图对象的屏幕位置与尺寸
  1906	     * 一起打出来 —— 一眼看出是容器没上移，还是视图自己被别处摆了位置。 */
  1907	    {
  1908	        lv_area_t a;
  1909	
  1910	        if (view->arrow != NULL) {
  1911	            lv_obj_get_coords(view->arrow, &a);
  1912	            syslog(LOG_DEBUG, "[map] arrow  y1=%d y2=%d cy=%d (地图可见窗口中心期望值见页面几何)",
  1913	                (int)a.y1, (int)a.y2, (int)((a.y1 + a.y2) / 2));
  1914	        }
  1915	    }
  1916	}
