  1918	/**
  1919	 * @brief 跟车：改中心经纬度。未越 overscan 只平移 canvas。
  1920	 */
  1921	void vmap_view_set_center(vmap_view_t * view, double lon, double lat)
  1922	{
  1923	    int now_x = 0;
  1924	    int now_y = 0;
  1925	    int base_x = 0;
  1926	    int base_y = 0;
  1927	    double dx;
  1928	    double dy;
  1929	    double limit;
  1930	
  1931	    if (!view) {
  1932	        return;
  1933	    }
  1934	
  1935	    vmap_latlong_to_pixel(lat, lon, view->zoom, &now_x, &now_y);
  1936	    vmap_latlong_to_pixel(view->render_lat, view->render_lon, view->zoom, &base_x, &base_y);
  1937	
  1938	    dx = (now_x - base_x) * view->scale;
  1939	    dy = (now_y - base_y) * view->scale;
  1940	    view->lon = lon;
  1941	    view->lat = lat;
  1942	
  1943	    /*
  1944	     * Follow must not decode tiles. vmap_tile_cache_warm() is a blocking
  1945	     * LFS parse (~150ms) on this thread; doing it every GNSS tick once pan
  1946	     * crossed the old prefetch threshold pinned bicycle_ui at ~80% idle~10%.
  1947	     * New tiles load in vmap_view_render_pump() when the canvas rebases.
  1948	     */
  1949	    limit = (double)view->margin - (double)VMAP_PAN_GUARD;
  1950	
  1951	    /*
  1952	     * 航向朝上时，屏上看到的是**旋转后**的视口：它的四角离骑手是半对角线
  1953	     * r = hypot(view_w/2, view_h/2)（240x216 → 161 px），画布必须盖住它，否则
  1954	     * 45° 附近四角露底。骑手到画布边的余量 = margin + view_h/2 - |pan|，要求
  1955	     * 不小于 r ⇒ pan <= margin - (r - view_h/2) - guard。取较紧的竖向。
  1956	     */
  1957	    if (view->heading_up) {
  1958	        const double r = hypot((double)view->view_w / 2.0,
  1959	            (double)view->view_h / 2.0);
  1960	
  1961	        limit -= r - (double)view->view_h / 2.0;
  1962	        if (limit < 8.0) {
  1963	            limit = 8.0;
  1964	        }
  1965	    }
  1966	
  1967	    if (dx >= -limit && dx <= limit && dy >= -limit && dy <= limit) {
  1968	        bicycle_c_debug_map_soft_pan();
  1969	        vmap_view_apply_canvas_pos(view, dx, dy);
  1970	        vmap_follow_log(view, lon, lat);
  1971	        return;
  1972	    }
  1973	
  1974	    /* Soft-pan even when tiles cannot be reloaded (BLE LFS hold / in-flight pump). */
  1975	    if (view->pump_phase != 0 || myvendor_mtp_lfs_quiesce()) {
  1976	        bicycle_c_debug_map_soft_pan();
  1977	        vmap_view_apply_canvas_pos(view,
  1978	            vmap_clamp_d(dx, -limit, limit),
  1979	            vmap_clamp_d(dy, -limit, limit));
  1980	        vmap_follow_log(view, lon, lat);
  1981	        return;
  1982	    }
  1983	
  1984	    bicycle_c_debug_map_full_render();
  1985	    vmap_view_render(view);
  1986	}
