  1988	/**
  1989	 * @brief 绑定定位箭头所在 LVGL 层。
  1990	 */
  1991	void vmap_view_set_y_bias(vmap_view_t * view, int32_t bias)
  1992	{
  1993	    if (!view || view->y_bias == bias) {
  1994	        return;
  1995	    }
  1996	
  1997	    view->y_bias = bias;
  1998	
  1999	    /* 清掉角度去重，让箭头下一次更新必定重新摆位；否则角度没变就早退，
  2000	     * 箭头会留在偏置之前的位置上。 */
  2001	    view->last_arrow_angle10 = INT32_MIN;
  2002	
  2003	    /* 画布立刻按新偏置重摆一次：导航开始/结束时地图常常是静止的，
  2004	     * 不能等下一次 pan 才生效。还没摆过（last_pan_* 未初始化）就交给下一次。 */
  2005	    if (view->canvas && view->last_pan_px != INT32_MIN
  2006	        && view->last_pan_py != INT32_MIN) {
  2007	        /* 走同一套位置公式：航向朝上时它还要做旋转补偿，不能在这里重写一遍。 */
  2008	        view->last_pan_px = INT32_MIN;
  2009	        view->last_pan_py = INT32_MIN;
  2010	        vmap_view_apply_canvas_pos(view, view->pan_dx, view->pan_dy);
  2011	    }
  2012	}
