  1854	/* 分段计时（诊断）：`on_gpx_timer` 里几段重活的耗时，整拍 >=60 ms 时打一行
  1855	 * `[gpx] total=… nav=… follow=… track=… dem=…`（LOG_DEBUG）。 */
  1856	#define MAP_GPX_STALL_PARTS 8
