  1865	
  1866	    LV_UNUSED(vis0);
  1867	    LV_UNUSED(cov0);
  1868	    LV_UNUSED(pending0);
  1869	    LV_UNUSED(fix_ok);
  1870	
  1871	    if (total >= 60u && s_stall_n > 0) {
  1872	        char buf[128];
  1873	        int off = 0;
  1874	        int i;
  1875	
  1876	        for (i = 0; i < s_stall_n && off < (int)sizeof(buf) - 24; i++) {
  1877	            off += snprintf(buf + off, sizeof(buf) - (size_t)off, "%s=%ums ",
  1878	                s_stall_tag[i], (unsigned)s_stall_ms[i]);
  1879	        }
  1880	        syslog(LOG_DEBUG, "[gpx] total=%ums %s", (unsigned)total, buf);
  1881	    }
